// A single hash mod a KNOWN prime with a KNOWN base is forgeable: an attacker
// precomputes a Thue-Morse-style anti-hash string that collides. Two independent
// (base, mod) pairs seeded at runtime make that precomputation impossible.
struct DoubleHash {
    static const long long M1 = 1000000007LL, M2 = 998244353LL;
    long long B1, B2;
    vector<long long> h1, h2, p1, p2;

    explicit DoubleHash(const string& s) {
        mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());
        B1 = 131 + (long long)(rng() % 100) * 2;    // random odd-ish bases each run
        B2 = 137 + (long long)(rng() % 100) * 2;
        int n = (int)s.size();
        h1.assign(n + 1, 0); h2.assign(n + 1, 0);
        p1.assign(n + 1, 1); p2.assign(n + 1, 1);
        for (int i = 0; i < n; ++i) {
            h1[i+1] = (h1[i] * B1 + s[i]) % M1;
            h2[i+1] = (h2[i] * B2 + s[i]) % M2;
            p1[i+1] = p1[i] * B1 % M1;
            p2[i+1] = p2[i] * B2 % M2;
        }
    }
    // inclusive [l, r]; compare PAIRS only, never one component
    pair<long long,long long> get(int l, int r) const {
        long long a = ((h1[r+1] - h1[l] * p1[r-l+1]) % M1 + M1) % M1;
        long long b = ((h2[r+1] - h2[l] * p2[r-l+1]) % M2 + M2) % M2;
        return {a, b};
    }
};

// ENGINE 1 -- KMP. Deterministic, O(m) extra memory.
int countKmp(const string& s, const string& p) {
    if (p.empty() || p.size() > s.size()) return 0;
    vector<int> lps(p.size(), 0);
    for (size_t i = 1, len = 0; i < p.size(); ) {
        if (p[i] == p[len]) lps[i++] = (int)++len;
        else if (len)       len = lps[len - 1];
        else                lps[i++] = 0;
    }
    int count = 0;
    for (size_t i = 0, j = 0; i < s.size(); ) {
        if (s[i] == p[j]) {
            ++i; ++j;
            if (j == p.size()) { ++count; j = lps[j - 1]; }   // continue, allow overlap
        }
        else if (j) j = lps[j - 1];
        else        ++i;
    }
    return count;
}

// ENGINE 2 -- Z algorithm on p + separator + s. Simplest correctness proof.
int countZ(const string& s, const string& p) {
    if (p.empty() || p.size() > s.size()) return 0;
    string t = p + '\x01' + s;                 // separator must not occur in either
    int n = (int)t.size();
    vector<int> z(n, 0);
    for (int i = 1, l = 0, r = 0; i < n; ++i) {
        if (i < r) z[i] = min(r - i, z[i - l]);
        while (i + z[i] < n && t[z[i]] == t[i + z[i]]) ++z[i];
        if (i + z[i] > r) { l = i; r = i + z[i]; }
    }
    int count = 0;
    for (int i = (int)p.size() + 1; i < n; ++i)
        if (z[i] >= (int)p.size()) ++count;
    return count;
}

