def count_kmp(s: str, p: str) -> int:
    """ENGINE 1 -- KMP. Deterministic, O(m) extra memory."""
    if not p or len(p) > len(s):
        return 0
    lps = [0] * len(p)
    length, i = 0, 1
    while i < len(p):
        if p[i] == p[length]:
            length += 1; lps[i] = length; i += 1
        elif length:
            length = lps[length - 1]
        else:
            lps[i] = 0; i += 1
    count = i = j = 0
    while i < len(s):
        if s[i] == p[j]:
            i += 1; j += 1
            if j == len(p):
                count += 1
                j = lps[j - 1]          # continue, allowing overlaps
        elif j:
            j = lps[j - 1]
        else:
            i += 1
    return count


def count_z(s: str, p: str) -> int:
    """ENGINE 2 -- Z algorithm on p + separator + s."""
    if not p or len(p) > len(s):
        return 0
    t = p + "\x01" + s                  # separator must occur in neither
    n = len(t)
    z = [0] * n
    l = r = 0
    for i in range(1, n):
        if i < r:
            z[i] = min(r - i, z[i - l])
        while i + z[i] < n and t[z[i]] == t[i + z[i]]:
            z[i] += 1
        if i + z[i] > r:
            l, r = i, i + z[i]
    return sum(1 for i in range(len(p) + 1, n) if z[i] >= len(p))


def count_hash(s: str, p: str, base: int = 131, mod: int = 1000000007) -> int:
    """ENGINE 3 -- rolling polynomial hash. Fastest in practice, probabilistic."""
    if not p or len(p) > len(s):
        return 0
    m = len(p)
    target = 0
    for ch in p:
        target = (target * base + ord(ch)) % mod
    power = pow(base, m, mod)
    cur, count = 0, 0
    for i, ch in enumerate(s):
        cur = (cur * base + ord(ch)) % mod
        if i >= m:
            cur = (cur - ord(s[i - m]) * power) % mod
        if i >= m - 1 and cur == target and s[i - m + 1:i + 1] == p:
            count += 1                  # verify: hash equality alone is not proof
    return count

