string shortestPalindrome(const string& s) {
    if (s.empty()) return s;
    string rev(s.rbegin(), s.rend());
    string t = s + '\x01' + rev;        // separator prevents the border overrunning s
    vector<int> lps(t.size(), 0);
    for (size_t i = 1, len = 0; i < t.size(); ) {
        if (t[i] == t[len]) lps[i++] = (int)++len;
        else if (len)       len = lps[len - 1];
        else                lps[i++] = 0;
    }
    int keep = lps.back();               // length of the longest palindromic prefix
    return rev.substr(0, s.size() - keep) + s;
}

