def shortest_palindrome(s: str) -> str:
    if not s:
        return s
    rev = s[::-1]
    t = s + "\x01" + rev            # separator prevents the border overrunning s
    lps = [0] * len(t)
    length, i = 0, 1
    while i < len(t):
        if t[i] == t[length]:
            length += 1; lps[i] = length; i += 1
        elif length:
            length = lps[length - 1]
        else:
            lps[i] = 0; i += 1
    keep = lps[-1]                  # length of the longest palindromic prefix
    return rev[:len(s) - keep] + s

