// Bounded n (<= 1000). Every substring gets an O(1) double hash from prefix
// tables; the set size is the answer.
long long countDistinctSubstrings(const string& s) {
    DoubleHash H(s);
    int n = (int)s.size();
    set<pair<long long,long long>> seen;
    for (int i = 0; i < n; ++i)
        for (int j = i; j < n; ++j)
            seen.insert(H.get(i, j));
    return (long long)seen.size();
}
// The O(n) answer is a suffix automaton: it has at most 2n-1 states, and the
// number of distinct substrings is the sum over states of (len[v] - len[link[v]]).
// A suffix array with LCP gives the same count in O(n log n).

