def count_distinct_substrings(s: str) -> int:
    """Bounded n (<= 1000). Every substring gets an O(1) double hash.

    The O(n) answer is a SUFFIX AUTOMATON: at most 2n-1 states, and the count is
    sum over states of (len[v] - len[link[v]]). A suffix array with LCP gives the
    same number in O(n log n). This O(n^2) version is the right tool only because
    the constraint caps n at 1000."""
    h = DoubleHash(s, b1=131, b2=137)     # fixed bases keep the test deterministic
    n = len(s)
    seen = set()
    for i in range(n):
        for j in range(i, n):
            seen.add(h.get(i, j))
    return len(seen)

