struct PalindromeQueries {
    int n;
    DoubleHash fwd, bwd;
    // bwd is built over reverse(s) using the SAME bases, so the hashes are comparable
    PalindromeQueries(const string& s)
        : n((int)s.size()), fwd(s), bwd(string(s.rbegin(), s.rend())) {}

    bool isPalindrome(int l, int r) const {
        // s[l..r] reversed lives at rev[n-1-r .. n-1-l]
        return fwd.get(l, r) == bwd.get(n - 1 - r, n - 1 - l);
    }
};

