class PalindromeQueries:
    """O(n) preprocessing, O(1) per query."""

    def __init__(self, s: str):
        self.n = len(s)
        # SAME bases for both, or the hashes are not comparable
        self.fwd = DoubleHash(s, b1=131, b2=137)
        self.bwd = DoubleHash(s[::-1], b1=131, b2=137)

    def is_palindrome(self, l: int, r: int) -> bool:
        # s[l..r] reversed lives at rev[n-1-r .. n-1-l]
        return self.fwd.get(l, r) == self.bwd.get(self.n - 1 - r, self.n - 1 - l)

