bool repeatedSubstringPattern(const string& s) {
    int n = (int)s.size();
    if (n < 2) return false;
    vector<int> lps(n, 0);
    for (int i = 1, len = 0; i < n; ) {
        if (s[i] == s[len]) lps[i++] = ++len;
        else if (len)       len = lps[len - 1];
        else                lps[i++] = 0;
    }
    int period = n - lps[n - 1];        // smallest period of the whole string
    return lps[n - 1] > 0 && n % period == 0;
}

