def repeated_substring_pattern(s: str) -> bool:
    n = len(s)
    if n < 2:
        return False
    lps = [0] * n
    length, i = 0, 1
    while i < n:
        if s[i] == s[length]:
            length += 1; lps[i] = length; i += 1
        elif length:
            length = lps[length - 1]
        else:
            lps[i] = 0; i += 1
    period = n - lps[n - 1]        # smallest period of the whole string
    return lps[n - 1] > 0 and n % period == 0
